text:
.expanding-row:not([hidden]),
.actionable-item:not([hidden]) {
  display: grid;
  grid-template-columns: 1fr auto;

  & .expand-button,
  & .delete-button {
    padding-inline: var(--calendar-dialog-row-expand-button-padding-inline-start) var(--calendar-dialog-row-padding-inline);
    padding-block: 0;
    margin: 0;
    min-inline-size: 0;
    align-self: stretch;
    aspect-ratio: 0;
    border: 0;
  }
}

.actionable-item {
  align-items: center;
}

#reminderList {
  padding-inline-start: 0;
  margin-block: 0;
}
